1	#include "krnl_config.h"
2	
3	extern "C" {
4	
5	#define INPUT_DIM 2
6	#define SP_LEN 256
7	#define DIS_LEN 128
8	
9	const int NUM_OF_TILES = 32774/NUM_KERNEL;
10	
11	void load(int flag, int tile_idx, INTERFACE_WIDTH* local_SP, volatile INTERFACE_WIDTH* searchSpace)
12	{
13	#pragma HLS INLINE OFF
14		if (flag){
15			for (int i(0); i<SP_LEN; ++i){
16			#pragma HLS PIPELINE II=1
17				local_SP[i] = searchSpace[tile_idx*SP_LEN+i];
18			}
19		}
20	}
21	
22	void compute(int flag, float* local_Query, INTERFACE_WIDTH* local_SP, float* local_distance)
23	{
24	#pragma HLS INLINE OFF
25		if (flag){
26			for (int ii = 0; ii < SP_LEN; ii+=2) {
27			#pragma HLS PIPELINE II=1
28				float delta_squared_sum = 0.0;	
29				for (int kk = 0; kk < INPUT_DIM; ++kk){
30				#pragma HLS UNROLL				
31					uint32_t sp_dim_item = local_SP[ii+kk].range(31, 0);
32					float sp_dim_item_value = *((float*)(&sp_dim_item));
33					float delta = sp_dim_item_value - local_Query[kk];
34					delta_squared_sum += delta * delta;
35				}
36				local_distance[ii/2] = delta_squared_sum;
37			}
38		}
39	}
40	
41	void swap(float* a, float* b, int* x, int* y)
42	{
43		float tmp_1;
44		int tmp_2;
45	
46		tmp_1 = *a;
47		*a = *b;
48		*b = tmp_1;
49	
50		tmp_2 = *x;
51		*x = *y;
52		*y = tmp_2;
53	}
54	
55	void sort(int flag, int start_id, float* local_distance, float* local_kNearstDist, int* local_kNearstId)
56	{
57	#pragma HLS INLINE OFF
58		if (flag){
59			for (int i = 0; i < DIS_LEN; ++i) {
60			#pragma HLS PIPELINE II=1
61				local_kNearstDist[0] = local_distance[i];
62				local_kNearstId[0] = start_id + i;
63				//compare and swap odd
64				for(int ii=1; ii<TOP+1; ii+=2){
65				#pragma HLS UNROLL
66				#pragma HLS DEPENDENCE variable="local_kNearstDist" inter false
67				#pragma HLS DEPENDENCE variable="local_kNearstId" inter false
68					if(local_kNearstDist[ii] < local_kNearstDist[ii+1]){
69						swap(&local_kNearstDist[ii], &local_kNearstDist[ii+1], &local_kNearstId[ii], &local_kNearstId[ii+1]);
70				    }
71				}
72				//compare and swap even
73				for(int ii=1; ii<TOP+1; ii+=2){
74				#pragma HLS UNROLL
75				#pragma HLS DEPENDENCE variable="local_kNearstDist" inter false
76				#pragma HLS DEPENDENCE variable="local_kNearstId" inter false
77					if(local_kNearstDist[ii] > local_kNearstDist[ii-1]){
78						swap(&local_kNearstDist[ii], &local_kNearstDist[ii-1], &local_kNearstId[ii], &local_kNearstId[ii-1]);
79					}
80				}
81			}
82		}
83		else{
84			for (int i=0; i<TOP+2; ++i){
85			#pragma HLS UNROLL
86				local_kNearstDist[i] = MAX_FLT;
87				local_kNearstId[i] = -1;
88			}
89		}
90	}
91	
92	void krnl_partialKnn(
93		volatile float* inputQuery,     // input query
94		volatile INTERFACE_WIDTH* searchSpace,    // search space
95		hls::stream<pkt> &kNearstDist,			     // output distance array
96		hls::stream<pkt> &kNearstId			     // output id array
97	){
98		#pragma HLS INTERFACE m_axi port=inputQuery offset=slave bundle=gmem1
99		#pragma HLS INTERFACE m_axi port=searchSpace offset=slave bundle=gmem1
